<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';
$error=null;$msg=null;$rows=[];$user=[];$p=bi_step22_period($_GET['month']??null);
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.view');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!security_step17_has_permission($pdo,'bi.manage',$user))throw new RuntimeException('Executive BI manage permission required.');$action=(string)($_POST['action']??'save');if($action==='save'){bi_step22_save_target($pdo,$orgId,$_POST,(int)$user['id']);$msg='Target saved.';}elseif($action==='archive'){bi_step22_target_status($pdo,$orgId,(int)($_POST['id']??0),'archived');$msg='Target archived.';}}$metrics=bi_step22_metrics($pdo,$orgId,$p['start'],$p['end']);$rows=bi_step22_targets($pdo,$orgId,$p['start'],$p['end'],$metrics);$all=$pdo->prepare("SELECT * FROM bi_targets WHERE organization_id=? ORDER BY period_start DESC,id DESC LIMIT 100");$all->execute([$orgId]);$allRows=$all->fetchAll();}catch(Throwable $e){$error=$e->getMessage();$allRows=[];}
$catalog=bi_step22_metric_catalog();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>BI Targets - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="executive_bi.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • KPI Targets</small></span></a><div class="os-top-actions"><a class="os-btn" href="executive_bi.php">Executive BI</a><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><main class="os-main" style="max-width:1420px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">MANAGEMENT TARGETS</div><h1>Set explicit targets. The system never invents them.</h1><p>Each target is measured against the selected period using the same live KPI engine as Executive BI.</p></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=bi_step22_h($msg)?></div><?php endif;?><?php if(!$error):?><section class="bi-grid" style="margin-top:14px"><article class="os-card bi-span-6"><div class="os-title-row"><div><h2>Create Target</h2><p>Higher/lower direction and unit are derived from the selected metric.</p></div></div><form method="post" class="bi-form"><input type="hidden" name="action" value="save"><div class="bi-field wide"><label>Metric</label><select name="metric_code" required><?php foreach($catalog as $k=>$v):?><option value="<?=bi_step22_h($k)?>"><?=bi_step22_h($v[0])?></option><?php endforeach;?></select></div><div class="bi-field"><label>Target Value</label><input type="number" min="0" step="0.001" name="target_value" required></div><div class="bi-field wide"><label>Target Name</label><input name="target_name" maxlength="190" placeholder="Optional custom name"></div><div class="bi-field"><label>Start</label><input type="date" name="period_start" value="<?=bi_step22_h($p['start'])?>" required></div><div class="bi-field"><label>End</label><input type="date" name="period_end" value="<?=bi_step22_h($p['end'])?>" required></div><div class="bi-field full"><label>Notes</label><textarea name="notes" rows="3"></textarea></div><div class="bi-field full"><button class="os-btn primary">Save Target</button></div></form></article><article class="os-card bi-span-6"><div class="os-title-row"><div><h2><?=bi_step22_h($p['label'])?> Target Status</h2><p>Actual values are live, not cached.</p></div></div><?php if(!$rows):?><div class="bi-note"><b>No active target covers this month.</b></div><?php endif;?><?php foreach($rows as $t):$pct=$t['achievement_pct']===null?0:min(100,max(0,(float)$t['achievement_pct']));?><div class="bi-target"><div class="bi-target-head"><div><b><?=bi_step22_h($t['target_name'])?></b><small class="bi-muted"><?=bi_step22_h($t['metric_name'])?> • <?=bi_step22_h($t['direction_code'])?></small></div><strong class="<?=$t['met']===true?'bi-good':($t['met']===false?'bi-warn':'')?>"><?=$t['achievement_pct']===null?'N/A':number_format((float)$t['achievement_pct'],1).'%'?></strong></div><div class="bi-progress"><span style="width:<?=$pct?>%"></span></div><small class="bi-muted">Actual <?=bi_step22_num($t['actual_value']??0,2)?> • Target <?=bi_step22_num($t['target_value'],2)?></small></div><?php endforeach;?></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Target Register</h2><p>Archived targets remain in history.</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Code</th><th>Metric</th><th>Period</th><th>Target</th><th>Unit</th><th>Direction</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$allRows):?><tr><td colspan="8">No targets configured.</td></tr><?php endif;?><?php foreach($allRows as $r):?><tr><td><?=bi_step22_h($r['target_code'])?></td><td><?=bi_step22_h($catalog[$r['metric_code']][0]??$r['metric_code'])?></td><td><?=bi_step22_h($r['period_start'])?> → <?=bi_step22_h($r['period_end'])?></td><td><?=bi_step22_num($r['target_value'],3)?></td><td><?=bi_step22_h($r['unit_code'])?></td><td><?=bi_step22_h($r['direction_code'])?></td><td><?=bi_step22_h(strtoupper((string)$r['status']))?></td><td><?php if($r['status']==='active'):?><form method="post"><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="os-btn">Archive</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?></main></body></html>